// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createToken, getTokensList, deleteToken } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const tokenName = uniqueSuffix("testbot-lifecycle");

    const tokensPostResponse = await createToken(client, headers, tokenName);

    expect(getResponseValue(tokensPostResponse, "response.name"), 'name').toBe(tokenName);
    expect(getResponseValue(tokensPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(tokensPostResponse, "response.token"), 'token').toMatch(/^[0-9a-f]{64}$/i);
    expect(getResponseValue(tokensPostResponse, "response.expires"), 'expires').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const createdTokenId = getResponseValue(tokensPostResponse, "response.id");

    const tokensGetResponse = await getTokensList(client, headers);

    // The listing is ordered createdAt desc, so the token just created is index 0.
    expect(getResponseValue(tokensGetResponse, "response.0.id"), 'listed id').toBe(createdTokenId);
    expect(getResponseValue(tokensGetResponse, "response.0.name"), 'listed name').toBe(tokenName);
    expect(getResponseValue(tokensGetResponse, "response.0.revoked"), 'listed revoked').toBe(false);
    expect(getResponseValue(tokensGetResponse, "response.0.createdAt"), 'listed createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(tokensGetResponse, "response.0.expires"), 'listed expires').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(tokensGetResponse, "response.0.token"), 'listing carries no token value').toBeNull();

    const tokensTokensDeleteResponse = await deleteToken(
        client,
        headers,
        createdTokenId
    );

    const tokensGet1Response = await getTokensList(client, headers);

    expect(tokensGet1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(tokensGet1Response, "response.0.id"), 'listed id after revoke').toBe(createdTokenId);
    expect(getResponseValue(tokensGet1Response, "response.0.name"), 'listed name after revoke').toBe(tokenName);
    expect(getResponseValue(tokensGet1Response, "response.0.revoked"), 'listed revoked after revoke').toBe(true);
    expect(getResponseValue(tokensGet1Response, "response.0.token"), 'listing carries no token value after revoke').toBeNull();
});
